package com.wms.controller;import com.wms.common.Result;import com.wms.dto.*;import com.wms.service.WorkflowService;import com.wms.repository.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/workflows")@PreAuthorize("hasAuthority('system:workflow')")public class WorkflowController{private final WorkflowService s;private final RoleRepository roles;private final UserRepository users;public WorkflowController(WorkflowService s,RoleRepository r,UserRepository u){this.s=s;roles=r;users=u;}@GetMapping public Result<List<WorkflowDTO>> list(){return Result.ok(s.list());}@GetMapping("/candidates")public Result<Map<String,Object>> candidates(){return Result.ok(Map.of("roles",roles.findAll().stream().filter(x->x.isEnabled()).map(x->Map.of("value",x.getCode(),"label",x.getName())).toList(),"users",users.findAll().stream().filter(x->x.isEnabled()).map(x->Map.of("value",x.getUsername(),"label",x.getDisplayName()==null?x.getUsername():x.getDisplayName())).toList()));}@PostMapping public Result<WorkflowDTO> create(@Valid@RequestBody WorkflowSaveReq q){return Result.ok(s.save(null,q));}@PutMapping("/{id}")public Result<WorkflowDTO> update(@PathVariable Long id,@Valid@RequestBody WorkflowSaveReq q){return Result.ok(s.save(id,q));}}
